import {getServiceDetail} from './serviceDetails';

export interface ArchitectureProfileField {
  key:string;label:string;kind:'text'|'select'|'number'|'boolean';
  options?:string[];min?:number;max?:number;help:string;
}
export interface ArchitectureProfileData {
  purpose:string;objectives:string[];fields:ArchitectureProfileField[];
  sources:{title:string;url:string;verified:string}[];limitations:string[];
}
const date='2026-11-01';
const t=(key:string,label:string,help:string):ArchitectureProfileField=>({key,label,kind:'text',help});
const s=(key:string,label:string,options:string[],help:string):ArchitectureProfileField=>({key,label,kind:'select',options,help});
const b=(key:string,label:string,help:string):ArchitectureProfileField=>({key,label,kind:'boolean',help});
const n=(key:string,label:string,min:number,max:number,help:string):ArchitectureProfileField=>({key,label,kind:'number',min,max,help});
const ref=(title:string,url:string)=>({title,url,verified:date});
const common='DVA-C03 study configuration, not an AWS deployment or exhaustive console schema. Missing values mean unknown. A declared control is not proof that AWS permissions, reachability or runtime behavior were verified.';
function p(id:string,purpose:string,objectives:string[],fields:ArchitectureProfileField[],sources?:ArchitectureProfileData['sources'],limitations:string[]=[]):ArchitectureProfileData {
  return {purpose,objectives,fields,sources:sources??getServiceDetail(id)?.sources.slice(0,2)??[],limitations:[common,...limitations]};
}

